head.b:skin:
/* Variable definitions
<Group description="Colors" selector="body">
<Variable name="keycolor" description="Accent color" type="color" default="#3949ab" value="#3949ab"/>
<Variable name="page.background" description="Page background" type="color" default="#ffffff" value="#ffffff"/>
<Variable name="text.color" description="Text color" type="color" default="#1f2933" value="#1f2933"/>
</Group>
*/

/* Slate - minimal, zero-JS, mobile-first Blogger theme.
   No external requests: system fonts, inline CSS, no webfonts, no scripts. */

:root{
  --accent:$(keycolor);
  --bg:$(page.background);
  --text:$(text.color);
  --muted:#64748b;
  --border:#e2e8f0;
  --soft:#f1f5f9;
}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{
  margin:0;
  background:var(--bg);
  color:var(--text);
  font:1rem/1.65 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
}
.wrap{max-width:46rem;margin-inline:auto;padding-inline:1rem}
a{color:var(--accent);text-decoration:none}
a:hover{text-decoration:underline}
img{max-width:100%;height:auto}

.site-header{border-bottom:1px solid var(--border);padding-block:1.25rem}
.header-inner{display:flex;flex-wrap:wrap;align-items:center;gap:.5rem 1.25rem}
.site-title{font-size:1.375rem;font-weight:700;line-height:1.2;margin:0}
.site-title a{color:inherit}
.pages-section ul{display:flex;flex-wrap:wrap;gap:0 1rem;list-style:none;margin:0;padding:0}
.pages-section a{color:var(--muted);font-size:.9375rem}
.search-form{margin-inline-start:auto}
.search-form input{
  max-width:10rem;padding:.375rem .625rem;font:inherit;
  border:1px solid var(--border);border-radius:.375rem;background:var(--bg);color:var(--text);
}

.site-main{padding-block:1rem 2rem}
.results-note{color:var(--muted);font-size:.9375rem}

.post-summary{padding-block:1.5rem;border-bottom:1px solid var(--border)}
.post-summary:last-of-type{border-bottom:0}
.post-title{font-size:1.5rem;line-height:1.25;margin:.25rem 0}
.post-title a{color:inherit}
.post-meta{color:var(--muted);font-size:.875rem;margin:.25rem 0 .75rem}
.post-labels a{display:inline-block;margin-inline-start:.5rem}
.post-thumb{display:block;margin-bottom:.75rem}
.post-thumb img{display:block;width:100%;border-radius:.5rem}
.post-snippet{color:#334155}

.post-full .post-title{font-size:2rem}
.post-body{overflow-wrap:break-word}
.post-body img{border-radius:.5rem}
.post-body blockquote{
  margin-inline:0;padding-inline-start:1rem;
  border-inline-start:3px solid var(--border);color:var(--muted);
}
.post-body pre{overflow-x:auto;padding:1rem;background:var(--soft);border-radius:.5rem;font-size:.9em}
.post-body table{border-collapse:collapse;display:block;overflow-x:auto}
.post-body th,.post-body td{border:1px solid var(--border);padding:.4rem .7rem}
.read-more{font-weight:600}

.pager{display:flex;justify-content:space-between;gap:1rem;padding-block:1.5rem}
.pager a{font-weight:600}

.comments{margin-top:2.5rem;padding-top:1rem;border-top:1px solid var(--border)}
.comment-form input[type="text"],.comment-form textarea{max-width:100%}
#comment-editor{width:100% !important;max-width:100%}

.site-footer{
  border-top:1px solid var(--border);color:var(--muted);
  font-size:.875rem;padding-block:1.5rem;text-align:center;
}

@media (min-width:48rem){
  .post-title{font-size:1.625rem}
  .post-full .post-title{font-size:2.25rem}
}
